"""Reproduce the reviewed Pack source profile, with no game execution or media."""
import argparse,hashlib,json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
def generate(src):
 rows=[]
 for r in src['rows']:
  rows.append({'id':r['id'],'from':r['epoch'],'until':r['until'],'capable':r['pairDeclared']and not r['factoryBoundary'],'pack':r['attackTimes']['packtime']['nativeBinderAfterZeroDefault']or 1.0,'unpack':r['attackTimes']['unpacktime']['nativeBinderAfterZeroDefault']or 1.0,'unpacked_idle':'UnpackedIdle'in r['stateNames'],'visual':r['visual']})
 digest=hashlib.sha256(json.dumps(rows,sort_keys=True,separators=(',',':')).encode()).digest()
 code='// Generated locally from verified source UnitModel states and attack binder defaults.\n'
 code+='#[derive(Clone,Copy,Debug)] pub struct Spec{pub id:u16,pub from:u8,pub until:u8,pub capable:bool,pub pack:f32,pub unpack:f32,pub unpacked_idle:bool,pub visual:&\'static str}\n'
 code+='pub const SOURCE_HASH:[u8;32]=['+','.join(str(v)for v in digest)+'];\n'
 code+='pub const ROWS:&[Spec]=&[\n'
 for r in rows:code+='Spec{id:%d,from:%d,until:%d,capable:%s,pack:%s_f32,unpack:%s_f32,unpacked_idle:%s,visual:%s},\n'%(r['id'],r['from'],r['until'],str(r['capable']).lower(),str(float(r['pack'])),str(float(r['unpack'])),str(r['unpacked_idle']).lower(),json.dumps(r['visual']))
 code+='];\npub fn lookup(id:u16,epoch:u8)->Option<Spec>{ROWS.iter().copied().filter(|r|r.id==id&&r.from<=epoch&&epoch<r.until).max_by_key(|r|r.from)}\n'
 return code.encode(),{'sourceHash':digest.hex(),'rows':len(rows),'capableRows':sum(r['capable']for r in rows)}
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--inventory',type=pathlib.Path,default=ROOT.parent/'pack8-source-inventory.json');p.add_argument('--out',type=pathlib.Path,default=ROOT/'src/pack8_defs.rs');p.add_argument('--verify',action='store_true');a=p.parse_args();code,report=generate(json.loads(a.inventory.read_text()))
 if a.verify:
  if a.out.read_bytes()!=code:raise ValueError('Pack source profile differs from reviewed generated bytes')
 else:a.out.write_bytes(code)
 print(json.dumps({'status':'passed',**report,'moduleSha256':hashlib.sha256(code).hexdigest()}))
